#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int x;
    while (scanf("%d", &x) == 1) {
        int first = -1;
        for (int i = 0; i < n; i++) {
            if (values[i] == x) {
                first = i;
                break;
            }
        }
        if (first < 0) {
            printf("нет\n");
            continue;
        }
        int last = first;
        for (int i = n - 1; i > first; i--) {
            if (values[i] == x) {
                last = i;
                break;
            }
        }
        printf("%d %d\n", first + 1, last + 1);
    }
    return 0;
}

