#include <string.h>

typedef struct {
    char name[21];
    int score;
} Record;

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) {
        return 0;
    }
    Record records[100];
    for (int i = 0; i < n; i++) {
        scanf("%20s %d", records[i].name, &records[i].score);
    }
    char query[21];
    while (scanf("%20s", query) == 1) {
        int found = -1;
        for (int i = 0; i < n; i++) {
            if (strcmp(records[i].name, query) == 0) {
                found = i;
                break;
            }
        }
        if (found >= 0) {
            printf("%d\n", records[found].score);
        } else {
            printf("не найден\n");
        }
    }
    return 0;
}

