#include <stdio.h>

static int find(const int *values, int n, int x, long long *comparisons) {
    for (int i = 0; i < n; i++) {
        (*comparisons)++;
        if (values[i] == x) {
            return i;
        }
    }
    return -1;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return 0;
    }
    int plain[1000], mtf[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &plain[i]);
        mtf[i] = plain[i];
    }
    long long plain_cost = 0, mtf_cost = 0;
    int x;
    while (scanf("%d", &x) == 1) {
        find(plain, n, x, &plain_cost);
        int p = find(mtf, n, x, &mtf_cost);
        if (p > 0) {
            int value = mtf[p];
            for (int i = p; i > 0; i--) {
                mtf[i] = mtf[i - 1];
            }
            mtf[0] = value;
        }
    }
    printf("обычный: %lld\n", plain_cost);
    printf("в начало: %lld\n", mtf_cost);
    return 0;
}

